//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is safe to retry.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Values below one
    /// still permit the required first call.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempts = 0;
    let mut delay_ms = config.base_delay_ms.min(config.max_delay_ms);

    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempts >= max_attempts => {
                return Err(error);
            }
            Err(_) => {
                sleeper.sleep_ms(delay_ms);
                delay_ms = delay_ms.saturating_mul(2).min(config.max_delay_ms);
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(4, 10, 25), &mut sleeper, || {
            calls += 1;
            if calls < 4 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 4);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(5, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_first_call() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(3, 1, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("temporary".into()))
        });

        assert!(matches!(result, Err(RetryError::Transient(_))));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![1, 2]);
    }

    #[test]
    fn delay_saturation_cannot_overflow() {
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(4, u64::MAX, u64::MAX), &mut sleeper, || {
            Err(RetryError::Transient("temporary".into()))
        });

        assert!(result.is_err());
        assert_eq!(sleeper.sleeps, vec![u64::MAX; 3]);
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
    RetryConfig {
        max_attempts,
        base_delay_ms,
        max_delay_ms,
    }
}

#[test]
fn public_api_retries_transient_failures_until_success() {
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config(4, 10, 25), &mut sleeper, || {
        attempts += 1;
        if attempts == 3 {
            Ok(())
        } else {
            Err(RetryError::Transient("temporary outage".into()))
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(attempts, 3);
    assert_eq!(sleeper.sleeps, vec![10, 20]);
}

#[test]
fn public_api_stops_at_attempt_budget_and_returns_last_error() {
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config(2, 5, 50), &mut sleeper, || {
        attempts += 1;
        Err(RetryError::Transient(format!("failure {attempts}")))
    });

    assert_eq!(result, Err(RetryError::Transient("failure 2".into())));
    assert_eq!(attempts, 2);
    assert_eq!(sleeper.sleeps, vec![5]);
}

#[test]
fn zero_attempt_budget_still_makes_the_first_call() {
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config(0, 1, 10), &mut sleeper, || {
        attempts += 1;
        Err(RetryError::Transient("temporary".into()))
    });

    assert_eq!(result, Err(RetryError::Transient("temporary".into())));
    assert_eq!(attempts, 1);
    assert!(sleeper.sleeps.is_empty());
}
